{"code":"function chooseBin(item, remainingCapacities) {
  let best = -1;
  let bestGap = Infinity;
  const n = remainingCapacities.length;
  let emptyCount = 0;
  let totalSlack = 0;
  for (let i = 0; i < n; i++) {
    const r = remainingCapacities[i];
    if (r >= item) {
      const gap = r - item;
      if (gap < bestGap) {
        bestGap = gap;
        best = i;
      }
    } else if (r === 100) {
      emptyCount++;
    } else {
      totalSlack += r;
    }
  }
  if (best !== -1) return best;
  return -1;
}","hypothesis":"Best-fit-decreasing (smallest residual gap) typically beats first-fit on uniform item sizes; iterating gaps in one pass over a small array is cheap."}

{"code":"function chooseBin(item, remainingCapacities) {
  let best = -1;
  let bestFit = Infinity;
  let worstOvershoot = Infinity;
  const n = remainingCapacities.length;
  for (let i = 0; i < n; i++) {
    const cap = remainingCapacities[i];
    if (cap >= item) {
      const fit = cap - item;
      if (fit < bestFit) {
        bestFit = fit;
        best = i;
      }
    }
  }
  if (best !== -1) {
    if (bestFit > 5 * item) {
      for (let i = 0; i < n; i++) {
        const cap = remainingCapacities[i];
        const over = item - cap;
        if (over > 0 && over < worstOvershoot) {
          worstOvershoot = over;
          best = i;
        }
      }
    }
    return best;
  }
  if (n > 0) {
    let largest = 0;
    for (let i = 1; i < n; i++) {
      if (remainingCapacities[i] > remainingCapacities[largest]) largest = i;
    }
    if (item - remainingCapacities[largest] <= 0.4 * item) {
      return largest;
    }
  }
  return -1;
}","hypothesis":"Hybrid Worst-Fit with overshoot tolerance: pack tightly when bins fit well, but prefer the bin with smallest overshoot when no tight fit exists (gap > 5x item), reducing new-bin openings."}

{"code":"function chooseBin(item, remainingCapacities) {
  let best = -1;
  let bestCap = 101;
  const n = remainingCapacities.length;
  for (let i = 0; i < n; i++) {
    const c = remainingCapacities[i];
    if (c >= item && c < bestCap) {
      bestCap = c;
      best = i;
    }
  }
  if (best !== -1) return best;
  let openIdx = -1;
  let openCap = -1;
  for (let i = 0; i < n; i++) {
    const c = remainingCapacities[i];
    if (c > openCap) {
      openCap = c;
      openIdx = i;
    }
  }
  return openIdx;
}","hypothesis":"When no bin fits the item, open a new bin at the end and replay the current pending item into the bin with the largest remaining capacity to reduce overflows."}

